<script setup lang="ts">
import { friendlyError } from '@lostsky/api/client'; import LsButton from '@lostsky/ui/components/LsButton.vue'; import LsField from '@lostsky/ui/components/LsField.vue'; import LsInlineError from '@lostsky/ui/components/LsInlineError.vue'; import LsPageHeader from '@lostsky/ui/components/LsPageHeader.vue'; import LsFormActions from '@lostsky/ui/components/LsFormActions.vue'; import LsFormSection from '@lostsky/ui/components/LsFormSection.vue'; import { useMutation,useQuery } from '@tanstack/vue-query'; import { NInput,NInputNumber,NSelect } from 'naive-ui'; import { computed,reactive } from 'vue'; import { useRouter } from 'vue-router'; import { manageApi } from '../../lib'
const router=useRouter();const form=reactive({product_id:null as number|null,customer_id:null as number|null,handler_entity_id:null as number|null,sender_entity_id:null as number|null,cs_entity_id:null as number|null,quantity:1,memo:''});const options=useQuery({queryKey:['manage-options'],queryFn:manageApi.options});const products=useQuery({queryKey:['manage-product-options'],queryFn:()=>manageApi.products({page:1,limit:100,is_active:1})});const entities=computed(()=>(options.data.value?.entities??[]).map(e=>({label:e.name,value:Number(e.entity_id??e.id)})));const customers=computed(()=>(options.data.value?.customers??[]).map(c=>({label:c.nickname||c.name||`客户 #${c.id}`,value:c.id})));const productOptions=computed(()=>(products.data.value?.list??[]).map((p:any)=>({label:`${p.name} · ¥${Number(p.price).toFixed(2)}`,value:Number(p.id)})));const save=useMutation({mutationFn:()=>manageApi.createOrder({...form,memo:form.memo.trim()||null}),onSuccess:data=>router.push(`/manage/orders/${data.id}`)});const valid=computed(()=>Boolean(form.product_id&&form.quantity>=1))
</script><template><div class="manage-page"><LsPageHeader title="新建订单" description="由服务端重新读取商品并计算价格与分配；服务商品和卡商品无需选择接单人。" back-to="/manage/orders" back-label="返回订单"/><form class="manage-form" @submit.prevent="save.mutate()"><LsFormSection title="商品与客户"><LsField label="商品" for-id="order-product" required><NSelect id="order-product" v-model:value="form.product_id" :options="productOptions" filterable placeholder="选择已上架商品"/></LsField><LsField label="数量" for-id="order-quantity" required><NInputNumber id="order-quantity" v-model:value="form.quantity" :min="1" :max="999"/></LsField><LsField label="客户" for-id="order-customer" hint="使用客户预存款或交付服务权益时选择。"><NSelect id="order-customer" v-model:value="form.customer_id" :options="customers" filterable clearable placeholder="可选"/></LsField></LsFormSection><LsFormSection title="参与方"><LsField label="接单人" for-id="order-handler"><NSelect id="order-handler" v-model:value="form.handler_entity_id" :options="entities" filterable clearable placeholder="普通商品可选"/></LsField><LsField label="发单人" for-id="order-sender"><NSelect id="order-sender" v-model:value="form.sender_entity_id" :options="entities" filterable clearable/></LsField><LsField label="客服" for-id="order-cs"><NSelect id="order-cs" v-model:value="form.cs_entity_id" :options="entities" filterable clearable/></LsField><LsField label="备注" for-id="order-memo"><NInput id="order-memo" v-model:value="form.memo" type="textarea" maxlength="500" show-count/></LsField></LsFormSection><LsInlineError v-if="save.isError.value" :message="friendlyError(save.error.value)"/><LsFormActions><LsButton type="button" variant="secondary" @click="router.back()">取消</LsButton><LsButton type="submit" :disabled="!valid" :loading="save.isPending.value">创建订单</LsButton></LsFormActions></form></div></template>
